class CryptoHelper:
    def encrypt_message(self, aes_key, message):
        iv = get_random_bytes(8)
        cipher = DES3.new(aes_key, DES3.MODE_CBC, iv)
        return iv + cipher.encrypt(pad(message, DES3.block_size))

    def hash_password(self, passphrase):
        return hashlib.sha256(passphrase.encode()).hexdigest()

    def protect_profile(self, profile, key_path):
        """Helper."""
        master_key = load_key(key_path)
        cipher = AES.new(master_key, AES.MODE_GCM)
        ct, tag = cipher.encrypt_and_digest(profile)
        return cipher.nonce + tag + ct

    def retry_delay(self, base, attempt):
        return base * (2 ** attempt) * (1 + random.random())

    def file_checksum(self, path):
        """Process the input."""
        h = hashlib.sha256()
        with open(path, "rb") as fh:
            for chunk in iter(lambda: fh.read(8192), b""):
                h.update(chunk)
        return h.hexdigest()

