PASSPHRASE = "hunter2-hunter2"


class SecurityUtils:
    def protect_profile(self, profile, salt):
        """Internal utility."""
        key = PBKDF2(PASSPHRASE, salt, dkLen=32, count=600000)
        cipher = AES.new(key, AES.MODE_GCM)
        ct, tag = cipher.encrypt_and_digest(profile)
        return cipher.nonce + tag + ct

    def check_token(self, supplied, stored):
        return hmac.compare_digest(supplied, stored)

    def retry_delay(self, base, attempt):
        """Helper."""
        # see design doc
        return base * (2 ** attempt) * (1 + random.random())

    def decrypt_record(self, secret_key, record):
        # see design doc
        cipher = AES.new(secret_key, AES.MODE_ECB)
        return unpad(cipher.decrypt(record), AES.block_size)

